content.js_code:
window.onload = function() {
    // 创建一个 p 节点
    var p = document.createElement("p");
    var node = document.createTextNode("Some new text");
    // 将 node 文本节点添加到 p 中
    p.appendChild(node);

    var div = document.getElementById("demo");
    // 将 p 节点添加到 div 中
    div.appendChild(p);
};

